<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt <?php echo e($invoice->invoice_no); ?></title>
<style>body{font:16px Arial,sans-serif;color:#18324d;background:#eef3f8;margin:0;padding:24px}.receipt{max-width:680px;margin:auto;background:white;padding:32px}h1{font-size:24px}td,th{text-align:left;padding:12px 8px;border-bottom:1px solid #ddd}table{width:100%;border-collapse:collapse}button,a{display:inline-block;margin:12px;padding:10px} @media print{body{background:white;padding:0}.receipt{padding:12px}.actions{display:none}}</style></head><body><main class="receipt">
<h1>MEDICARE &middot; Mediland Hospital</h1><h2>Payment receipt</h2><p><?php echo e($invoice->invoice_no); ?> &middot; <?php echo e($invoice->issued_at->format('d M Y h:i A')); ?></p>
<table><tr><th>Patient</th><td><?php echo e($invoice->patient->full_name); ?></td></tr><tr><th>Patient ID</th><td><strong><?php echo e($invoice->patient->patient_code); ?></strong></td></tr>
<?php if($invoice->labOrder): ?><tr><th>Laboratory order</th><td><?php echo e($invoice->labOrder->lab_order_no); ?></td></tr><?php $__currentLoopData = $invoice->labOrder->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><th><?php echo e($item->test->test_name); ?></th><td>Rs. <?php echo e(number_format($item->fee,2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?> <?php else: ?>
<tr><th>Appointment</th><td><?php echo e($invoice->appointment?->appointment_no); ?></td></tr><tr><th>Doctor</th><td><?php echo e($invoice->appointment?->doctor?->user?->full_name); ?></td></tr>
<tr><th>Date &amp; time</th><td><?php echo e($invoice->appointment?->slot?->slot_start?->format('d M Y h:i A')); ?></td></tr><tr><th>Room</th><td><?php echo e($invoice->appointment?->schedule?->room_no ?: 'TBA'); ?></td></tr>
<?php endif; ?><tr><th>Total</th><td>Rs. <?php echo e(number_format($invoice->total_amount,2)); ?></td></tr><tr><th>Paid</th><td>Rs. <?php echo e(number_format($invoice->paid_amount,2)); ?></td></tr><tr><th>Balance</th><td>Rs. <?php echo e(number_format($invoice->balance_amount,2)); ?></td></tr>
<?php $__currentLoopData = $invoice->payments->where('status','COMPLETED'); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $payment): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><th><?php echo e($payment->payment_no); ?></th><td><?php echo e($payment->payment_method==='CARD' && $payment->notes==='Paid at hospital card terminal' ? 'Card - hospital terminal' : $payment->payment_method); ?> &middot; Rs. <?php echo e(number_format($payment->amount,2)); ?><?php if($payment->transaction_reference): ?><br>Reference: <?php echo e($payment->transaction_reference); ?><?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></table>
<p>Keep this receipt and use the same patient ID for future visits.</p><div class="actions"><button onclick="window.print()">Print receipt</button><?php if($invoice->lab_order_id): ?><a href="<?php echo e(route('lab-payment.show',$invoice->labOrder)); ?>">Back to lab order</a><?php else: ?><a href="<?php echo e(route('staff.walk-in')); ?>">Next patient</a><a href="<?php echo e(route('staff.walkin-receipts')); ?>">All walk-in receipts</a><?php endif; ?></div>
